require_once __DIR__ . '/includes/auth.php'; require_staff();$pdo=db();
$reportTypes=$pdo->query('SELECT report_type,COUNT(*) total FROM blotters GROUP BY report_type ORDER BY total DESC')->fetchAll();$docTypes=$pdo->query('SELECT document_type,COUNT(*) total FROM document_requests GROUP BY document_type ORDER BY total DESC')->fetchAll();$statuses=$pdo->query('SELECT status,COUNT(*) total FROM blotters GROUP BY status')->fetchAll();$totalReports=(int)$pdo->query('SELECT COUNT(*) FROM blotters')->fetchColumn();$totalDocs=(int)$pdo->query('SELECT COUNT(*) FROM document_requests')->fetchColumn();$resolved=(int)$pdo->query("SELECT COUNT(*) FROM blotters WHERE status='Resolved'")->fetchColumn();$feedbackCount=(int)$pdo->query('SELECT COUNT(*) FROM feedback')->fetchColumn();$recent=$pdo->query('SELECT case_no,report_type,incident_type,complainant,location,status,created_at FROM blotters ORDER BY created_at DESC LIMIT 12')->fetchAll();$maxType=max(1,...array_map(fn($r)=>(int)$r['total'],$reportTypes));$maxDoc=max(1,...array_map(fn($r)=>(int)$r['total'],$docTypes));$pageTitle='Reports & analytics';$activePage='reports';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Reports / Analytics desk</div><h1>Reports & analytics</h1><p>Generate itemized reports with charts, categories, designated signatory, and export-ready formats.</p></div><div class="export-actions"><a class="secondary-button" href="report_export.php?format=pdf">PDF</a><a class="secondary-button" href="report_export.php?format=csv">CSV</a><a class="primary-button" href="report_export.php?format=word">Word</a></div></section><section class="report-meta panel"><div><span>Report period</span><strong><?= h(date('F Y')) ?></strong></div><div><span>Prepared by</span><strong><?= h(current_user()['full_name']) ?></strong></div><div><span>Designated signatory</span><strong>Hon. Roberto Reyes · Punong Barangay</strong></div><div><span>Generated</span><strong><?= h(date('M d, Y h:i A')) ?></strong></div></section><div class="stats-grid"><div class="stat-card"><div class="stat-icon amber">▣</div><span class="stat-label">Total reports</span><strong><?= $totalReports ?></strong><small>All categories</small></div><div class="stat-card"><div class="stat-icon blue">▤</div><span class="stat-label">Documents requested</span><strong><?= $totalDocs ?></strong><small>All document types</small></div><div class="stat-card"><div class="stat-icon mint">✓</div><span class="stat-label">Reports resolved</span><strong><?= $resolved ?></strong><small><?= $totalReports?round($resolved/$totalReports*100):0 ?>% resolution rate</small></div><div class="stat-card"><div class="stat-icon violet">♡</div><span class="stat-label">Feedback received</span><strong><?= $feedbackCount ?></strong><small>Resident voice</small></div></div><div class="analytics-grid"><section class="panel chart-panel"><div class="card-header"><div><div class="eyebrow">Categorized reports</div><h2>Reports by type</h2></div><span class="muted">Itemized count</span></div><div class="bar-chart"><?php foreach($reportTypes as $row): ?><div class="bar-row"><div><span><?= h($row['report_type']) ?></span><strong><?= h($row['total']) ?></strong></div><div class="bar-track"><i style="width:<?= (int)$row['total']/$maxType*100 ?>%"></i></div></div><?php endforeach; ?><?php if(!$reportTypes): ?><p class="empty-state">No reports recorded yet.</p><?php endif; ?></div></section><section class="panel chart-panel"><div class="card-header"><div><div class="eyebrow">Document demand</div><h2>Requests by document</h2></div><span class="muted">Itemized count</span></div><div class="bar-chart mint-chart"><?php foreach($docTypes as $row): ?><div class="bar-row"><div><span><?= h($row['document_type']) ?></span><strong><?= h($row['total']) ?></strong></div><div class="bar-track"><i style="width:<?= (int)$row['total']/$maxDoc*100 ?>%"></i></div></div><?php endforeach; ?><?php if(!$docTypes): ?><p class="empty-state">No document requests yet.</p><?php endif; ?></div></section></div><section class="panel chart-panel"><div class="card-header"><div><div class="eyebrow">Status distribution</div><h2>Resolution graph</h2></div><span class="muted">Current case statuses</span></div><div class="status-graph"><?php foreach($statuses as $row): ?><div class="status-column"><div class="status-bar" style="height:<?= $totalReports?(int)$row['total']/$totalReports*150:8 ?>px"></div><strong><?= h($row['total']) ?></strong><span><?= h($row['status']) ?></span></div><?php endforeach; ?></div></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Itemized report</div><h2>Report register</h2></div><span class="muted">Designated signatory: Hon. Roberto Reyes</span></div><div class="table-wrap"><table><thead><tr><th>Case no.</th><th>Category / incident</th><th>Complainant</th><th>Location</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td class="mono"><?= h($row['case_no']) ?></td><td><strong><?= h($row['report_type']) ?></strong><small class="cell-subtext"><?= h($row['incident_type']) ?></small></td><td><?= h($row['complainant']) ?></td><td><?= h($row['location']) ?></td><td><span class="status-pill <?= h(strtolower(str_replace(' ','-',$row['status']))) ?>"><i></i><?= h($row['status']) ?></span></td><td class="muted"><?= h(date('M d, Y',strtotime($row['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
